import { NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { db } from '@/lib/db';

export async function GET(request) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const employerProfile = await db.query(
      'SELECT id FROM employer_profiles WHERE user_id = $1',
      [session.user.id]
    );

    if (!employerProfile.rows[0]) {
      return NextResponse.json({ error: 'Employer profile not found' }, { status: 404 });
    }

    const { searchParams } = new URL(request.url);
    const status = searchParams.get('status');
    const page = parseInt(searchParams.get('page') || '1');
    const limit = parseInt(searchParams.get('limit') || '20');
    const offset = (page - 1) * limit;

    let query = `
      SELECT a.*, jp.title as job_title, sp.first_name, sp.last_name
      FROM applications a
      JOIN job_postings jp ON a.job_id = jp.id
      JOIN student_profiles sp ON a.student_id = sp.id
      WHERE jp.employer_id = $1
    `;
    const params = [employerProfile.rows[0].id];

    if (status) {
      query += ` AND a.status = $${params.length + 1}`;
      params.push(status);
    }

    query += ` ORDER BY a.applied_at DESC LIMIT $${params.length + 1} OFFSET $${params.length + 2}`;
    params.push(limit, offset);

    const result = await db.query(query, params);

    return NextResponse.json({
      applications: result.rows,
      pagination: { page, limit, total: result.rowCount }
    });
  } catch (error) {
    console.error('Error fetching applications:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

export async function POST(request) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const { job_id, student_id } = body;

    if (!job_id || !student_id) {
      return NextResponse.json({ error: 'job_id and student_id are required' }, { status: 400 });
    }

    const result = await db.query(
      `INSERT INTO applications (student_id, job_id, status) VALUES ($1, $2, 'applied') RETURNING *`,
      [student_id, job_id]
    );

    return NextResponse.json(result.rows[0], { status: 201 });
  } catch (error) {
    console.error('Error creating application:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

