export default function ClarificationsPage() {
  const { data: session } = useSession();
  const [clarifications, setClarifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchClarifications();
  }, []);

  async function fetchClarifications() {
    try {
      const res = await fetch('/api/clarifications?tenant_id=' + session.user.tenant_id);
      if (!res.ok) throw new Error('Failed to fetch');
      const data = await res.json();
      setClarifications(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }

  if (loading) return <LoadingSkeleton />;
  if (error) return <ErrorMessage message={error} onRetry={fetchClarifications} />;
  if (clarifications.length === 0) return <EmptyState message="No clarifications found" />;

  return (
    <div>
      {clarifications.map(clarification => (
        <ClarificationCard key={clarification.id} data={clarification} />
      ))}
    </div>
  );
}

