import { fetchDrives } from '@/lib/api';

export default function EmployerDrivesPage() {
  const { data: session } = useSession();
  const [drives, setDrives] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    async function loadDrives() {
      try {
        const data = await fetchDrives(session.user.tenantId);
        setDrives(data);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    }
    loadDrives();
  }, [session]);

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;
  if (drives.length === 0) return <div>No drives found.</div>;

  return (
    <div>
      <h1>My Drives</h1>
      <ul>
        {drives.map(drive => (
          <li key={drive.id}>{drive.title}</li>
        ))}
      </ul>
    </div>
  );
}

