import InterviewCard from '@/components/InterviewCard';

export default function EmployerInterviewsPage() {
  const { data: session } = useSession();
  const [interviews, setInterviews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!session?.user?.tenant_id) return;
    fetchInterviews();
  }, [session]);

  async function fetchInterviews() {
    try {
      setLoading(true);
      setError(null);
      const response = await api.get(`/api/employer/interviews?tenant_id=${session.user.tenant_id}`);
      setInterviews(response.data || []);
    } catch (err) {
      console.error('Failed to fetch interviews:', err);
      setError('Unable to load interviews. Please try again later.');
    } finally {
      setLoading(false);
    }
  }

  if (loading) return <LoadingSpinner />;
  if (error) return <ErrorAlert message={error} onRetry={fetchInterviews} />;
  if (interviews.length === 0) return <EmptyState message="No interviews scheduled yet." />;

  return (
    <div className="p-6">
      <h1 className="text-2xl font-bold mb-6">Interviews</h1>
      <div className="grid gap-4">
        {interviews.map(interview => (
          <InterviewCard key={interview.id} interview={interview} />
        ))}
      </div>
    </div>
  );
}

